DECLARE n NUMBER;
BEGIN
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='RH' AND TABLE_NAME='RH_REC_MAIL_LOT';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE RH.RH_REC_MAIL_LOT(LOTE_ID VARCHAR2(36) PRIMARY KEY, EMPRESA NUMBER(10) NOT NULL, ACTOR NUMBER(10) NOT NULL, NOMINA NUMBER(10) NOT NULL, PERIODO NUMBER(10) NOT NULL, ICP NUMBER(10) NOT NULL, ESTADO VARCHAR2(20) NOT NULL, SOLICITUD VARCHAR2(36), REVISION VARCHAR2(64) NOT NULL, CREADO DATE DEFAULT SYSDATE NOT NULL, VENCE DATE NOT NULL, MOTIVO VARCHAR2(500 CHAR))'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='RH' AND TABLE_NAME='RH_REC_MAIL_DET';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE RH.RH_REC_MAIL_DET(ITEM_ID NUMBER(10) PRIMARY KEY, LOTE_ID VARCHAR2(36) NOT NULL REFERENCES RH.RH_REC_MAIL_LOT(LOTE_ID), EMPRESA NUMBER(10) NOT NULL, PERSONA NUMBER(10) NOT NULL, NOMBRE VARCHAR2(250 CHAR), CORREO VARCHAR2(150), ESTADO VARCHAR2(20) NOT NULL, ERROR VARCHAR2(1000), FUENTE CLOB, HUELLA VARCHAR2(64), LOGO_HASH VARCHAR2(64), PDF BLOB, PDF_HASH VARCHAR2(64), TOKEN VARCHAR2(36), SOL_SMTP VARCHAR2(36) NOT NULL, INTENTOS NUMBER(5) DEFAULT 1 NOT NULL, ANTERIOR NUMBER(10), ACTUALIZADO DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT UK_RRM_SMTP UNIQUE(SOL_SMTP), CONSTRAINT UK_RRM_ITEM UNIQUE(LOTE_ID,PERSONA))'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='RH' AND TABLE_NAME='RH_REC_MAIL_CTL';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE RH.RH_REC_MAIL_CTL(EMPRESA NUMBER(10) PRIMARY KEY)'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='RH' AND TABLE_NAME='RH_REC_MAIL_GUARD';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE RH.RH_REC_MAIL_GUARD(EMPRESA NUMBER(10), PERSONA NUMBER(10), NOMINA NUMBER(10), PERIODO NUMBER(10), HUELLA VARCHAR2(64), ITEM_ID NUMBER(10) NOT NULL, CONSTRAINT PK_RRM_GUARD PRIMARY KEY(EMPRESA,PERSONA,NOMINA,PERIODO,HUELLA))'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_SEQUENCES WHERE SEQUENCE_OWNER='RH' AND SEQUENCE_NAME='SEQ_RH_REC_MAIL';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE SEQUENCE RH.SEQ_RH_REC_MAIL'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_INDEXES WHERE OWNER='RH' AND INDEX_NAME='IX_RRM_PENDING';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE INDEX RH.IX_RRM_PENDING ON RH.RH_REC_MAIL_DET(EMPRESA,ESTADO,ACTUALIZADO)'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_INDEXES WHERE OWNER='RH' AND INDEX_NAME='IX_RRM_ACTOR';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE INDEX RH.IX_RRM_ACTOR ON RH.RH_REC_MAIL_LOT(EMPRESA,ACTOR,CREADO)'; END IF;
END;
/
